local InoculationLadleMaker = {}
local PRODUCTS = {
    iron_inoculationladle = { name = "Železni inokulacijska zajemalka", ironCost = 3, woodCost = 2, leatherCost = 1, time = 5, cost = 150, prestige = 4, happiness = 2, description = "Železni inokulacijska zajemalka za livarje." },
    bronze_inoculationladle = { name = "Bronast inokulacijska zajemalka", bronzeCost = 3, ironCost = 1, woodCost = 2, leatherCost = 1, time = 7, cost = 365, prestige = 6, happiness = 3, description = "Bronast inokulacijska zajemalka za livarje." },
    silver_inoculationladle = { name = "Srebrn inokulacijska zajemalka", silverCost = 3, bronzeCost = 1, ironCost = 1, woodCost = 2, leatherCost = 1, time = 11, cost = 880, prestige = 11, happiness = 4, description = "Srebrn inokulacijska zajemalka za livarje." },
    gilded_inoculationladle = { name = "Pozlačen inokulacijska zajemalka", goldCost = 1, silverCost = 3, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 15, cost = 1900, prestige = 20, happiness = 5, description = "Pozlačen inokulacijska zajemalka za livarje." },
    jewel_set_inoculationladle = { name = "Draguljast inokulacijska zajemalka", goldCost = 2, silverCost = 3, jewelCost = 1, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 19, cost = 4100, prestige = 36, happiness = 7, description = "Draguljast inokulacijska zajemalka za livarje." },
    royal_sovereign_inoculationladle = { name = "Kraljevski suveren inokulacijska zajemalka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 26, cost = 8800, prestige = 68, happiness = 13, description = "Suveren inokulacijska zajemalka z biseri za krono." },
}
local BUILDINGS = {
    inoculationladle_workshop = { name = "Inoculationladle delavnica", cost = { gold = 325, wood = 185, stone = 130, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    inoculationladle_house = { name = "Inoculationladle hiša", cost = { gold = 1185, wood = 370, stone = 265, silver = 7, iron = 7 }, upkeep = 25, qualityBonus = 18 },
    master_inoculationladle_atelier = { name = "Mojstrski inoculationladle atelje", cost = { gold = 2975, wood = 425, stone = 515, silver = 35, gold = 7 }, upkeep = 70, qualityBonus = 30 },
    sovereign_inoculationladle_palace = { name = "Suverena inoculationladle palača", cost = { gold = 12920, wood = 650, stone = 825, gold = 83, jewel = 19 }, upkeep = 253, qualityBonus = 55, prestigeBonus = 50 },
}
InoculationLadleMaker.ironStock=18; InoculationLadleMaker.bronzeStock=14; InoculationLadleMaker.woodStock=10; InoculationLadleMaker.leatherStock=8; InoculationLadleMaker.silverStock=8; InoculationLadleMaker.goldStock=6; InoculationLadleMaker.jewelStock=4; InoculationLadleMaker.pearlStock=4
InoculationLadleMaker.productStock = {}; InoculationLadleMaker.buildings = {}; InoculationLadleMaker.maker = nil; InoculationLadleMaker.activeMaking = {}; InoculationLadleMaker.totalProducts = 0; InoculationLadleMaker.dayTimer = 0
function InoculationLadleMaker.init() InoculationLadleMaker.ironStock=18; InoculationLadleMaker.bronzeStock=14; InoculationLadleMaker.woodStock=10; InoculationLadleMaker.leatherStock=8; InoculationLadleMaker.silverStock=8; InoculationLadleMaker.goldStock=6; InoculationLadleMaker.jewelStock=4; InoculationLadleMaker.pearlStock=4; InoculationLadleMaker.productStock={}; InoculationLadleMaker.buildings={}; InoculationLadleMaker.maker=nil; InoculationLadleMaker.activeMaking={}; InoculationLadleMaker.totalProducts=0; InoculationLadleMaker.dayTimer=0; print("[InoculationLadleMaker] Royal Inoculation Ladle Maker System initialized (6 products, 4 buildings)") end
function InoculationLadleMaker.hireMaker(n,s) s=s or math.random(55,90); local c=585+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; InoculationLadleMaker.maker={name=n or ("Inokulant "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Inokulant najet: %s (spretnost: %d)",InoculationLadleMaker.maker.name,s),"success") end; return true end
function InoculationLadleMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function InoculationLadleMaker.build(id) local ok,e=InoculationLadleMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(InoculationLadleMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function InoculationLadleMaker.getQualityBonus() local b=0; for _,bd in ipairs(InoculationLadleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function InoculationLadleMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and InoculationLadleMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and InoculationLadleMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and InoculationLadleMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and InoculationLadleMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and InoculationLadleMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and InoculationLadleMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and InoculationLadleMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and InoculationLadleMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #InoculationLadleMaker.buildings==0 then return false,"Potrebna inokulacijska delavnica" end; if not InoculationLadleMaker.maker then return false,"Potreben inokulant" end; return true end
function InoculationLadleMaker.make(pt,qty) qty=qty or 1; local ok,e=InoculationLadleMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then InoculationLadleMaker.ironStock=InoculationLadleMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then InoculationLadleMaker.bronzeStock=InoculationLadleMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then InoculationLadleMaker.woodStock=InoculationLadleMaker.woodStock-d.woodCost*qty end; if d.leatherCost then InoculationLadleMaker.leatherStock=InoculationLadleMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then InoculationLadleMaker.silverStock=InoculationLadleMaker.silverStock-d.silverCost*qty end; if d.goldCost then InoculationLadleMaker.goldStock=InoculationLadleMaker.goldStock-d.goldCost*qty end; if d.jewelCost then InoculationLadleMaker.jewelStock=InoculationLadleMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then InoculationLadleMaker.pearlStock=InoculationLadleMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if InoculationLadleMaker.maker then t=math.max(1,t-math.floor(InoculationLadleMaker.maker.skill/13)) end; table.insert(InoculationLadleMaker.activeMaking,{id="inoculationladle_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function InoculationLadleMaker.completeMaking(m) local q=1.0+(InoculationLadleMaker.getQualityBonus()/100); if InoculationLadleMaker.maker then q=q+(InoculationLadleMaker.maker.skill/140) end; q=math.min(2.5,q); InoculationLadleMaker.productStock[m.productType]=(InoculationLadleMaker.productStock[m.productType] or 0)+m.quantity; InoculationLadleMaker.totalProducts=InoculationLadleMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if InoculationLadleMaker.maker then InoculationLadleMaker.maker.itemsMade=InoculationLadleMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then InoculationLadleMaker.maker.skill=math.min(100,InoculationLadleMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Inokulanka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"inoculationladle.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function InoculationLadleMaker.update(dt) if not _G.state then return end; InoculationLadleMaker.dayTimer=InoculationLadleMaker.dayTimer+dt; if InoculationLadleMaker.dayTimer>=30 then InoculationLadleMaker.dayTimer=0; for i=#InoculationLadleMaker.activeMaking,1,-1 do local m=InoculationLadleMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then InoculationLadleMaker.completeMaking(m); table.remove(InoculationLadleMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(InoculationLadleMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if InoculationLadleMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function InoculationLadleMaker.getStats() return {ironStock=InoculationLadleMaker.ironStock,bronzeStock=InoculationLadleMaker.bronzeStock,woodStock=InoculationLadleMaker.woodStock,leatherStock=InoculationLadleMaker.leatherStock,silverStock=InoculationLadleMaker.silverStock,goldStock=InoculationLadleMaker.goldStock,jewelStock=InoculationLadleMaker.jewelStock,pearlStock=InoculationLadleMaker.pearlStock,productStock=InoculationLadleMaker.productStock,numBuildings=#InoculationLadleMaker.buildings,hasMaker=InoculationLadleMaker.maker~=nil,makerName=InoculationLadleMaker.maker and InoculationLadleMaker.maker.name or "—",makerSkill=InoculationLadleMaker.maker and InoculationLadleMaker.maker.skill or 0,activeMaking=#InoculationLadleMaker.activeMaking,totalProducts=InoculationLadleMaker.totalProducts} end
return InoculationLadleMaker
